// PURE RECURSION
import java.util.*;
class MaxMoneyRobotCanEarn0 {
    public int maximumAmount(int[][] coins) {
        return dfs(coins, 0, 0, 2);
    }
    private int dfs(int[][] coins, int i, int j, int c){
        if(i==coins.length-1 && j==coins[0].length-1){
            if(coins[i][j]>=0) return coins[i][j];
            return c>0 ? 0: coins[i][j];
        }
        if(i>=coins.length || j>=coins[0].length) return Integer.MIN_VALUE/2;
        if(coins[i][j]>=0) {
            return coins[i][j] + Math.max(dfs(coins, i+1, j, c), dfs(coins, i, j+1, c));
        }
        int p1 = coins[i][j] + Math.max(dfs(coins, i+1, j, c), dfs(coins, i, j+1, c));
        if(c>0){
            int p2 = Math.max(dfs(coins, i+1, j, c-1), dfs(coins, i, j+1, c-1));
            return Math.max(p1, p2);
        }
        return p1;
    }
}
// RECURSION + MEMOIZATION
class MaxMoneyRobotCanEarn1 {
    public int maximumAmount(int[][] coins) {
        int m = coins.length, n =coins[0].length;
        int[][][] memo = new int[m][n][3];
        for(int[][] x: memo){
            for(int[] y: x)
                Arrays.fill(y, Integer.MIN_VALUE);
        }
        return dfs(coins, 0, 0, 2, memo);
    }
    private int dfs(int[][] coins, int i, int j, int c, int[][][] memo){
        if(i==coins.length-1 && j==coins[0].length-1){
            if(coins[i][j]>=0) return coins[i][j];
            return c>0 ? 0: coins[i][j];
        }
        if(i>=coins.length || j>=coins[0].length) return Integer.MIN_VALUE/2;
        if(memo[i][j][c]!=Integer.MIN_VALUE) return memo[i][j][c];
        if(coins[i][j]>=0) {
            return memo[i][j][c] = coins[i][j] + Math.max(dfs(coins, i+1, j, c, memo), dfs(coins, i, j+1, c, memo));
        }
        int p1 = coins[i][j] + Math.max(dfs(coins, i+1, j, c, memo), dfs(coins, i, j+1, c, memo));
        if(c>0){
            int p2 = Math.max(dfs(coins, i+1, j, c-1, memo), dfs(coins, i, j+1, c-1, memo));
            return memo[i][j][c] = Math.max(p1, p2);
        }
        return memo[i][j][c] = p1;
    }
}
